"""Synthetic OCR layouts for S6/S7 tests, generated by code so CI needs no `reference/` samples.

Hebrew is laid out right to left: `row` places the first text at the right edge and each next
text to its left, which is where a value sits relative to its label on a real form.
"""

from __future__ import annotations

from collections.abc import Sequence

from backend.core.models import (
    BarcodeHit,
    Box,
    ImageRef,
    OcrResult,
    OcrWord,
    ReaderName,
    Region,
    RegionKind,
)

ROW_HEIGHT = 0.016
WORD_GAP = 0.01
MIN_WORD_WIDTH = 0.04
CHAR_WIDTH = 0.012


def word_width(text: str) -> float:
    return max(MIN_WORD_WIDTH, CHAR_WIDTH * len(text))


def row(
    y: float, texts: Sequence[str], *, x_right: float = 0.9, conf: float = 0.9
) -> list[OcrWord]:
    """Words of one line, first text rightmost, centred on `y`."""
    words: list[OcrWord] = []
    x = x_right
    for text in texts:
        width = word_width(text)
        box: Box = (y - ROW_HEIGHT / 2, x - width, y + ROW_HEIGHT / 2, x)
        words.append(OcrWord(text=text, box=box, confidence=conf))
        x -= width + WORD_GAP
    return words


def page_ocr(*rows: Sequence[OcrWord]) -> OcrResult:
    words = [w for r in rows for w in r]
    return OcrResult(reader=ReaderName.tesseract, words=words, text=" ".join(w.text for w in words))


def region(kind: RegionKind, box: Box) -> Region:
    return Region(kind=kind, box=box, detector="test", score=1.0)


PATIENT_BOX: Box = (0.2, 0.05, 0.6, 0.95)


def patient_box() -> Region:
    return region(RegionKind.patient_box, PATIENT_BOX)


def barcode(payload: str, box: Box, nearby: Sequence[str] = ()) -> BarcodeHit:
    return BarcodeHit(
        payload=payload, symbology="code128", box=box, orientation_deg=0, nearby_text=list(nearby)
    )


def image_ref(width: int = 1000, height: int = 1400, kind: str = "color") -> ImageRef:
    return ImageRef(
        job_id="job",
        page_id="p1",
        kind=kind,  # type: ignore[arg-type]
        path=f"job/p1/{kind}",
        width=width,
        height=height,
        sha256="0" * 64,
    )
